INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('fe9ba6fa-d360-42e8-84d2-2a59a2e66bcc', '21feff02-016d-46e2-bb9d-c27495133b1b', '61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek', 'Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "75bcc60d-188d-4438-9b56-10fd65a07191", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "3779a084-3b25-435e-a786-6f790dda22c8", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "17d37f15-1a73-4edd-945d-9b0d95e22607", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "d9deaa9b-19e3-42da-a5c5-75e7fcc0590c", "text": "Igaz", "isCorrect": true}, {"id": "4621895a-243a-41ae-8773-75ff3aa3f386", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2cae621a-9deb-4bd1-80ae-0a0d09432ffb", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "55bb4ac8-ee54-4886-be87-293e35ee04ad", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "b5da8e88-b43f-445e-939d-cf71caedec77", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "a949df1b-beac-48b5-a132-2f8a7ca7a18e", "text": "Igaz", "isCorrect": true}, {"id": "266c4271-26f3-4728-8de8-36f95f1b802c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "df768e5d-8f16-49b8-833b-df9d954eacf6", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "82e32205-b5a6-4488-b127-ab646c2867e4", "text": "Igaz", "isCorrect": true}, {"id": "c5affda7-5957-4536-88a5-9940aa79ddd9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('5fd694d8-129a-4857-ab61-bcb7848cc8a6', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "e0559240-a0c5-4c1b-b39e-8b3cb53c34ff", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "f3deb6a0-5487-4b3c-ba74-bf0417e76155", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "f97f4684-c081-4aab-94d6-31cc7e76b7bd", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "5cbcd0f5-10c7-4eba-9078-fd2463a3d8ec", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "cfc65815-91d4-4597-8c73-b3e27a1d1522", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "55d385e5-fbec-4f42-9ccf-3984bf0b3490", "text": "Igaz", "isCorrect": true}, {"id": "eb09c981-5d01-44ed-8fa6-85a1a0d91f81", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2536c44b-efc0-4afe-a011-9dab60190272", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "c6178b36-f21e-4d4b-a90d-f48958c496e4", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "d617a7bb-ce23-49e2-b444-7437d5043939", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "75ffc08b-8c48-4d18-9a46-ec5170301806", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()),
('4c41b1b6-baa2-40dd-ab05-9be661f6a09e', '21feff02-016d-46e2-bb9d-c27495133b1b', '63. óra: Szerkesztési feladatok', 'Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "61af561c-c66b-4f15-bdbd-659c939c4805", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "ea0e7e7f-567b-4ef8-8f12-fc31148e5a2e", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "01170c04-d4bd-489e-be54-db1e6a6f6de1", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "e32050e6-436b-4946-9d8a-c75c6153356c", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "ca4a6c24-e01a-4b2a-8cd3-35383d689d87", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "e1b71f96-8ab3-45ee-ab3f-b8e681d29a38", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "086d95a4-9741-45da-a61c-84304771b2c1", "text": "Igaz", "isCorrect": true}, {"id": "cdcfd8c4-9723-4328-9ff5-9fa980970329", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5d8a6501-b720-48f6-9a2e-4c0eae924d9a", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "a5824513-04fc-4418-ae88-c60f488bb734", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "117c4039-0a18-4c08-beb5-0ced4f48c68a", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "e62396e8-c233-49db-aa9f-dafcf8a0647f", "text": "Igaz", "isCorrect": true}, {"id": "9dd93567-6600-4608-8e79-5c69dec37592", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ca660768-69d9-4867-95da-3fff814e7ab7", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "52fef67b-fbed-45e1-b6cd-e7eaefc44fc7", "text": "Igaz", "isCorrect": true}, {"id": "9389f114-176e-46b5-b5e4-f09e60c5c885", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc02fb07-f226-4e16-9820-ef7f01c85e61", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "2f7ef5c6-f064-4df6-b445-c908aae465ad", "text": "Igaz", "isCorrect": true}, {"id": "dc264649-35a3-4260-9479-6d574ad4214f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('23f6640c-74fd-4a27-aa7b-9f0f598dcbfe', '21feff02-016d-46e2-bb9d-c27495133b1b', '64. óra: Dinamikus szerkesztőprogram megismerése', 'Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "ed9b4361-f4a9-411d-b03d-3b095fb43af3", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "a15c5bd2-1634-4f7e-9c22-2cfb84121dbe", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "6fc4fb59-c7d5-4a70-8f5c-87b16cb1976e", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "2ad5b311-e1e6-4c20-a516-8c96d3824822", "text": "Videóvágásra", "isCorrect": false}, {"id": "1df214f7-b3ed-43c8-b5b6-d1ea6e8fd812", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "874936ef-3679-4aca-8fcc-8e01b84865e8", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "dbb847a3-14e4-45d3-b6bc-ea7667652034", "text": "Igaz", "isCorrect": true}, {"id": "847aab02-b606-426b-8970-293cbe559c9b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c177a58-a0e1-439f-ba52-004d25e42661", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "984de1c5-cfc8-4f34-ae38-1cbcc756024e", "text": "Igaz", "isCorrect": true}, {"id": "e9027f86-41f7-4896-8f7e-63c719f13fda", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "70a50d01-aedb-41ac-92c3-d0c361d9893f", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "131e48ca-eb49-426f-b852-7ae14b6a0f1c", "text": "Igaz", "isCorrect": true}, {"id": "5ce49ea9-5fb7-4ef9-bdce-02f7e6c38b30", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c34cf12c-d2bb-47cd-ac3b-b1835bad11c5", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "40119d93-7353-4a44-bbbf-48a9f0c4d66f", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "b63e9b21-a0b2-4b19-9a8e-a0a879f7e0aa", "text": "Színezés", "isCorrect": false}, {"id": "140495c4-d24c-43d9-8e7e-199b645b8aa7", "text": "Törlés", "isCorrect": false}, {"id": "f8954a38-96bc-4f14-85ab-2a4938209e83", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "0f5d166d-fd34-459c-afbb-b35c3875c66b", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "94ba549d-13dc-4fd9-9685-673a2a3b54c2", "text": "Igaz", "isCorrect": true}, {"id": "bc589d3a-9f9e-4fca-803e-5b995d444cdb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "599feb49-2942-4186-83bd-8ff723c05155", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]'::jsonb, true, NOW()),
('9016af82-a076-49d1-84b5-ecc8fee6ad05', '21feff02-016d-46e2-bb9d-c27495133b1b', '65. óra: Összefoglalás', 'A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "3a4145ae-eacc-495c-96dd-dd4fa3c201d7", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "15022032-6cba-40af-b80d-af44295c7904", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "df1528f1-c5ea-4318-be2b-ebfbe43fd3d6", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "75f1f595-2af9-4711-8ea4-ab94fdad8ad2", "text": "Igaz", "isCorrect": true}, {"id": "39a7cfaf-d1aa-493f-ab3a-1821a68aa9d1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "42c62748-2348-480e-b0a6-402b207aa45c", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "a596b84a-64d5-4517-8835-cffaeabdd0bf", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "14aa69d5-bea7-4656-927f-553f43d5a34a", "text": "Igaz", "isCorrect": true}, {"id": "2b4ac20c-c96a-4664-9a1a-adc3b7526015", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fb9a37f8-bac2-4144-8f43-2c9f967ccb45", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1fe2be80-e8f4-439a-a336-be278f2cf135", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "fb583309-28af-4699-84e3-a590df2f32f4", "text": "Igaz", "isCorrect": true}, {"id": "706770c9-41b9-4e6a-9475-98f5e292d671", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('5309819e-4d6d-4138-b2cb-273a126a5c71', '21feff02-016d-46e2-bb9d-c27495133b1b', '66. óra: Témazáró dolgozat', 'Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "eef20964-65bf-4d9d-9987-37d25a1441e3", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "68e290d5-7490-469c-b32d-f5b89e1a0c28", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "8d416dae-741f-4a2d-905a-7ee27f72b454", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "3c2af8ae-fb70-4814-84a6-8285e9f07a98", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "2e18432e-8a3d-46f8-b985-0045713a7876", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "4faada94-fa3b-4741-a805-0d107211c03d", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "f0d13cb4-1182-4e3b-afb2-68eac261fdd3", "text": "Igaz", "isCorrect": true}, {"id": "0eb6d354-8469-4d5d-b273-95bb092ac64d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a91c7720-0644-48a5-a72d-6f29bdbec589", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "60bf0471-2c07-4a32-b2ce-93cb440f5c4d", "text": "Igaz", "isCorrect": false}, {"id": "1bd2b90b-d81b-4794-9617-7ed53252cc47", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "d606e88e-219a-4750-8cac-33bc07d0b631", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "2ab83f4a-c5d9-4c83-bb2e-0fdc4977dd2c", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "4b2f7855-fb80-461c-997e-568c24e05669", "text": "Igaz", "isCorrect": true}, {"id": "1df6b417-d68d-4ff5-82da-ec226305064a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4286247d-1d13-4997-b5dd-ba59705b817d", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "1069f142-ea95-4838-83e5-07436bb6697d", "text": "Önmagában", "isCorrect": true}, {"id": "05e241e2-188c-4191-8d1b-7ce1a26d9149", "text": "Az origóban", "isCorrect": false}, {"id": "545004aa-e971-4c57-8a30-bac0c832ff6a", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "f208619d-9169-450a-88dd-61252fa8b36a", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('cae51fb9-34c5-4602-b9fb-80576203497e', '21feff02-016d-46e2-bb9d-c27495133b1b', '67. óra: Témazáró dolgozat értékelése', 'A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "54a862a6-29ce-4fba-9979-51e4e2d7f9e0", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "37a74b93-a289-4ec4-895d-1de57291e12f", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "39226869-ac3b-4e05-ac11-82746ef77946", "text": "A ceruza színe", "isCorrect": false}, {"id": "f7b9cc0f-469e-498f-95f5-680b357a7207", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "928fe5cb-3335-4a2d-bd69-e49b979db0bc", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "50f17345-2ee2-4709-9797-31a4241fa09c", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "d96e281a-6b79-4168-b18b-510d6a800c82", "text": "Igaz", "isCorrect": true}, {"id": "39a545c7-0159-496a-b9ac-61d57c51ea95", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0ce4725e-f9df-461a-b036-d6c31e770a1d", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "fa855976-e4e1-45ac-8cb0-4dc7438d44e1", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "51e0892d-7292-4716-951d-46a1c696ad88", "text": "Igaz", "isCorrect": true}, {"id": "0508b0cf-9bd4-4a75-91b5-53f58d127e0f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f9a7a5b3-cb85-405c-9130-365bba9c4dae", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "3f6d6ae3-32a7-4514-aa66-023896641301", "text": "Végtelen sok", "isCorrect": true}, {"id": "31c8a292-6886-4bee-bbb5-9aa5d686feb7", "text": "1", "isCorrect": false}, {"id": "d1afbb86-6ced-4477-a2cf-5f004c5515fc", "text": "2", "isCorrect": false}, {"id": "57a0053b-9f87-4bd2-851b-3deb96784048", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "ae660b18-69e5-48d9-bf1f-d79bd937e51e", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "a93bfabe-01e5-41ff-8f0b-94d813e6e4bc", "text": "Igaz", "isCorrect": true}, {"id": "cf791d18-f4a2-4e43-9673-71be037f70b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1057b320-58b2-448a-be39-3eedda0d1580", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()),
('59eea6a3-eb57-4405-ac60-cd641eaabaaa', '21feff02-016d-46e2-bb9d-c27495133b1b', '68. óra: Az arány fogalma', 'Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "13a507c3-d611-4520-8876-e575ad558c98", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "c029eb41-d759-4d3e-9da9-560305b543b5", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "d8ceabf1-d72b-4d58-b43c-14afcb873e67", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "f28ce3b0-c4a6-45c6-af4f-0621fa41f969", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "e336826a-2eaf-4d07-b155-af5d872f9ce3", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "244ea8f4-0e05-4a5d-97e0-28574c2a73d9", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "e5c29c5f-1139-41e1-b88b-df9f61898849", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "bd43c323-e8e4-4e59-8c22-5954dfc003d1", "text": "Plusz jellel", "isCorrect": false}, {"id": "29eccd3f-3563-4df1-9ef6-94b5107c8eba", "text": "Csillaggal", "isCorrect": false}, {"id": "4caa770e-5358-4056-9017-c19d2ec91408", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "c8c27bc7-fa69-415f-aabf-660d0e325e0b", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "b154b3d4-213c-4f56-81e1-294552dfd2c9", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "f1ab2006-df65-40c7-a88c-e7fe376cdd65", "text": "1 : 2", "isCorrect": false}, {"id": "455b0d36-7c97-489c-9b76-a9fcd2690e51", "text": "3 : 2", "isCorrect": false}, {"id": "50e7b7bd-ceee-421e-9474-5ca6a91edc06", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "9fe47622-3f89-459b-a727-9cc43ef85e7b", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "4f33644b-437b-4981-98cd-dc5e58b1254f", "text": "Igaz", "isCorrect": true}, {"id": "9bb76558-37a7-434a-854d-5da80fc31008", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c12c944-9a45-4507-804c-a3281b9e061d", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "fae64e5a-96c5-416c-b085-7373fc1fdb89", "text": "1 : 2", "isCorrect": true}, {"id": "99d7fab2-708d-4ea9-890c-620a1a40c309", "text": "2 : 4", "isCorrect": false}, {"id": "c4c379ca-c141-4228-af37-e0d87d569a35", "text": "1 : 4", "isCorrect": false}, {"id": "b3598b78-7005-488c-bfee-85a9675fd61e", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "18390bcb-cd6c-4189-9b25-96976b894a1a", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "c35f6de5-2f85-4799-91ca-65c47cfa7bae", "text": "Igaz", "isCorrect": true}, {"id": "ebd97dd6-986e-4742-85e0-f11ed71c6eb4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e3583b02-d294-4081-83ef-543951b8c41c", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "61f7560a-64c2-4944-a294-3095408e0a15", "text": "5 : 10", "isCorrect": true}, {"id": "8037888c-3a42-4083-b65e-dcbdfd43d29e", "text": "2 : 1", "isCorrect": false}, {"id": "90e53745-70bf-48b2-b224-50be031b3e06", "text": "3 : 5", "isCorrect": false}, {"id": "27eff818-c8bc-4f3c-971c-e7c3612af1c5", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('3151a093-de94-46cd-9e24-47de207983cf', '21feff02-016d-46e2-bb9d-c27495133b1b', '69. óra: Arányos osztás', 'Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "89c44afa-15ca-4947-a782-77a3a3de2879", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "aae70834-e9c4-4430-8d3f-dceb7baab80b", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "9e6cbafd-5f2d-4a41-b24b-59e4e7e303bf", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "d92668d9-246a-49a5-9b96-fa5cc4b6802d", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "c45216a0-6fa2-48ee-aa26-e5a35f3ba7c4", "text": "Igaz", "isCorrect": true}, {"id": "294b9e7c-49ee-4695-baff-87d774a28269", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a16579c9-5417-4413-894c-cdabd6af67e7", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "01558b16-484f-440a-9eb5-431270177816", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d2b41f98-1937-4206-b4cb-17741ee15cec", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "2d58448e-843a-4ce1-aa77-f6a07d00e08d", "text": "Igaz", "isCorrect": true}, {"id": "5b74b264-f54c-40ff-aed7-eacda6adeb71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('9e6ff8fe-eabd-409d-a466-43592e126173', '21feff02-016d-46e2-bb9d-c27495133b1b', '70. óra: Feladatok megoldása', 'Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "3e01b53c-a040-4f90-a018-a216959d4642", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "1e725a8a-5b3d-4ed5-be88-a87755ecbaa4", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "04093f69-204b-43cd-9dda-bdf4258e4424", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "8c50295c-f8ed-44a9-b02e-205314d4a13a", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "8417272c-60a0-46cf-b1b4-1160baf28f08", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d3a8bb50-60b0-4399-93f8-7071e378b4d2", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "b7a54359-5e74-498a-a2b0-e950bc81633e", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "ecab34ee-bdbe-45f6-9888-e866318ee585", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "fc2d39bc-fe70-46d6-8cd4-1e5c235c95b0", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "70deb8a8-ac04-4e2d-ae1f-2a746e83fd0a", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "d2797063-7a38-4445-b090-ca2f83d3aaec", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "0d20a785-4769-4f87-a241-16cd3cb7a492", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c07b78fe-2718-4fe0-83fb-44064110a27f", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "de58c413-ae1b-4deb-a5fc-794c44d713cf", "text": "Igaz", "isCorrect": true}, {"id": "0a0486e1-effc-468d-af00-a2030f2f64f5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;